window.renderMktFullTable = function() {
    const tbody = document.getElementById('mktFullTableBody');
    if (!tbody) return;
    const q = (document.getElementById('mktTableSearchInput')?.value || '').toLowerCase().trim();

    const filtered = window.MKT_SUBJECTS.filter(s =>
        !q ||
        s.nombre.toLowerCase().includes(q) ||
        s.id.toLowerCase().includes(q) ||
        s.area.toLowerCase().includes(q) ||
        s.componente.toLowerCase().includes(q) ||
        ('semestre ' + s.sem).includes(q)
    );

    tbody.innerHTML = filtered.map(s => `
        <tr onclick="window.openMktSubjectModal('${s.id}')" style="cursor:pointer;" onmouseover="this.style.background='#FFF7ED'" onmouseout="this.style.background=''">
            <td style="text-align:center; font-weight:800;">${s.id}</td>
            <td style="text-align:center; font-weight:800; color:#F39200;">Sem. ${s.sem}</td>
            <td style="text-align:center; font-size:0.7rem;">${s.bloque}</td>
            <td style="font-weight:800; color:#1A1A1B;">${s.nombre}</td>
            <td><span style="font-weight:700; color:${s.area==='Disciplinar'?'#C2410C':(s.area==='Transversal'?'#1E293B':'#15803D')};">${s.area}</span></td>
            <td style="font-size:0.71rem;">${s.componente}</td>
            <td style="text-align:center; font-weight:800;">${s.tipo}</td>
            <td style="text-align:center; font-weight:900;">${s.creditos}</td>
            <td style="text-align:center;">36 / 108</td>
            <td style="text-align:center;">48 / 96</td>
            <td style="text-align:center; font-weight:800;">144 h</td>
            <td><span style="background:${s.moodle.includes('100%')?'#F0FDF4':'#FFF7ED'}; color:${s.moodle.includes('100%')?'#15803D':'#C2410C'}; font-weight:800; font-size:0.68rem; padding:2px 6px; border-radius:4px;">${s.moodle}</span></td>
        </tr>
    `).join('');
};

window.showC3Section = function(targetId) {
    const panels = ['c3-malla-interactiva', 'c3-matriz-asignaturas', 'c3-competencias-rap', 'c3-epistemologia-modelo', 'c3-flexibilidad-grado', 'c3-inter-internacional'];
    panels.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = (id === targetId) ? 'block' : 'none';
    });
    const bar = document.getElementById('c3-subtabs-bar');
    if (bar) {
        bar.querySelectorAll('.c3-subtab-btn').forEach(btn => {
            const isTarget = btn.getAttribute('data-c3-target') === targetId;
            if (isTarget) {
                btn.style.background = '#1A1A1B';
                btn.style.color = '#FFFFFF';
                btn.style.border = '1.5px solid #F39200';
                btn.style.fontWeight = '800';
                btn.style.boxShadow = '0 2px 8px rgba(243,146,0,0.25)';
            } else {
                btn.style.background = '#F8FAFC';
                btn.style.color = '#334155';
                btn.style.border = '1px solid #CBD5E1';
                btn.style.fontWeight = '700';
                btn.style.boxShadow = 'none';
            }
        });
    }
    if (targetId === 'c3-malla-interactiva') window.renderMktMallaGrid();
    if (targetId === 'c3-matriz-asignaturas') window.renderMktFullTable();
};

window.c3Init = function() {
    window.renderMktMallaGrid();
    window.renderMktFullTable();
    window.showC3Section('c3-malla-interactiva');
};
